def irr(price,divs,terminal):
 lo,hi=-.95,3.
 for _ in range(150):
  m=(lo+hi)/2;pv=sum(d/(1+m)**(i+1) for i,d in enumerate(divs))+terminal/(1+m)**3
  if pv>price:lo=m
  else:hi=m
 return (lo+hi)/2
